--       支撑表仅清 Excel 导入批次（id 段或 creator 标记）；
--       保留公众号/视频号/小红书/企微/个微等 E2E seed 数据。
-- 本地 dev 仅重导 Excel（不动已有抖音/快手）时，可注释本段，仅用下方 ROLLBACK 段。

-- --- 1. 抖音/快手账号子表（按 account_id 限定） ---
-- 平台账号粉丝群
DELETE FROM oa_platform_account_fan_group WHERE tenant_id = 1 AND account_id IN (SELECT id FROM oa_account WHERE tenant_id = 1 AND platform_type IN ('DOUYIN', 'KUAISHOU'));
-- 账号成本
DELETE FROM oa_account_cost WHERE tenant_id = 1 AND account_id IN (SELECT id FROM oa_account WHERE tenant_id = 1 AND platform_type IN ('DOUYIN', 'KUAISHOU'));
-- 账号状态日志
DELETE FROM oa_account_status_log WHERE tenant_id = 1 AND account_id IN (SELECT id FROM oa_account WHERE tenant_id = 1 AND platform_type IN ('DOUYIN', 'KUAISHOU'));
-- 采集账号绑定
DELETE FROM oa_collector_account_bind WHERE tenant_id = 1 AND oa_account_id IN (SELECT id FROM oa_account WHERE tenant_id = 1 AND platform_type IN ('DOUYIN', 'KUAISHOU'));

-- --- 2. 平台账号：仅抖音/快手（tenant 全量，含历史手工录入） ---
-- 导入会整体替换抖音/快手，故删除 tenant_id=1 下全部 DOUYIN/KUAISHOU，不限 id 段。
DELETE FROM oa_account WHERE tenant_id = 1 AND platform_type IN ('DOUYIN', 'KUAISHOU');

-- --- 3. Excel 导入批次支撑表（ID 段 / creator；跳过仍被其他平台账号引用的行） ---
-- 实名人-中介关联（导入批次实名人）
DELETE FROM oa_realname_intermediary WHERE tenant_id = 1 AND realname_id IN (SELECT id FROM oa_realname WHERE tenant_id = 1 AND (id >= 110001 OR creator = 'xlsx-import-20260918'));
-- 公司扩容记录（导入批次公司）
DELETE FROM oa_company_expansion WHERE tenant_id = 1 AND company_id IN (SELECT id FROM oa_company WHERE tenant_id = 1 AND (id >= 100001 OR creator = 'xlsx-import-20260918'));
-- 手机卡（导入批次；无剩余账号引用）
DELETE FROM oa_sim_card WHERE tenant_id = 1 AND (id >= 130001 OR creator = 'xlsx-import-20260918') AND id NOT IN (SELECT sim_card_id FROM oa_account WHERE tenant_id = 1 AND sim_card_id IS NOT NULL);
-- 手机设备（导入批次；无剩余账号/SIM 引用）
DELETE FROM oa_phone WHERE tenant_id = 1 AND (id >= 120001 OR creator = 'xlsx-import-20260918') AND id NOT IN (SELECT phone_id FROM oa_account WHERE tenant_id = 1 AND phone_id IS NOT NULL) AND id NOT IN (SELECT phone_id FROM oa_sim_card WHERE tenant_id = 1 AND phone_id IS NOT NULL);
-- 实名人（导入批次；无剩余账号/设备引用）
DELETE FROM oa_realname WHERE tenant_id = 1 AND (id >= 110001 OR creator = 'xlsx-import-20260918') AND id NOT IN (SELECT realname_id FROM oa_account WHERE tenant_id = 1 AND realname_id IS NOT NULL) AND id NOT IN (SELECT realname_id FROM oa_phone WHERE tenant_id = 1 AND realname_id IS NOT NULL);
-- 公司（导入批次；无剩余账号引用）
DELETE FROM oa_company WHERE tenant_id = 1 AND (id >= 100001 OR creator = 'xlsx-import-20260918') AND id NOT IN (SELECT company_id FROM oa_account WHERE tenant_id = 1 AND company_id IS NOT NULL);

